import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as n,e as s}from"./app-f7ddf95e.js";const d={},c=s(`<h1 id="xmake-基于-lua-的跨平台构建工具" tabindex="-1"><a class="header-anchor" href="#xmake-基于-lua-的跨平台构建工具" aria-hidden="true">#</a> xmake（基于 Lua 的跨平台构建工具）</h1><blockquote><p>Homebrew 版本 3.0.5 ｜ 主页：见官方文档 ｜ 安装：<code>brew install xmake</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>xmake 是一个基于 Lua 语言开发的现代化跨平台构建工具，专注于「简单、快速、易用」三大目标。它解决的是传统构建系统（如 Makefile、CMake）语法繁琐、难以维护的问题：你只需编写一份 <code>xmake.lua</code> 描述文件，就能在 Windows、macOS、Linux、iOS、Android 等多个平台上完成编译、链接、打包、运行等全套工作。典型应用场景包括 C/C++ 项目的快速搭建、依赖库的自动下载与集成、以及需要跨平台分发或交叉编译的软件开发。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> xmake

<span class="token comment"># 升级到最新版本</span>
brew upgrade xmake

<span class="token comment"># 卸载</span>
brew uninstall xmake

<span class="token comment"># 查看版本信息</span>
xmake <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装完成后，运行 <code>xmake --version</code> 应能看到类似 <code>xmake v3.0.5+...</code> 的输出。若命令找不到，确认 Homebrew 的 bin 目录（通常是 <code>/opt/homebrew/bin</code> 或 <code>/usr/local/bin</code>）已在 <code>PATH</code> 中。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>xmake create</code></td><td>初始化一个新项目模板，<code>-l</code> 指定语言（c/c++/cuda 等），<code>-t</code> 指定模板类型（console/static/shared）</td><td><code>xmake create -l c++ -t console hello</code></td></tr><tr><td><code>xmake</code></td><td>默认执行编译构建，读取 <code>xmake.lua</code></td><td><code>xmake</code></td></tr><tr><td><code>xmake -r</code></td><td>重新构建（rebuild，强制重编译）</td><td><code>xmake -r</code></td></tr><tr><td><code>xmake run</code></td><td>运行目标程序，可加目标名参数</td><td><code>xmake run hello</code></td></tr><tr><td><code>xmake f</code></td><td>配置/重配置工程（如切换模式、平台）</td><td><code>xmake f -m debug</code></td></tr><tr><td><code>xmake f -p</code></td><td>指定编译平台（linux/macosx/windows/android/ios）</td><td><code>xmake f -p android</code></td></tr><tr><td><code>xmake f -m</code></td><td>指定构建模式（debug/release）</td><td><code>xmake f -m release</code></td></tr><tr><td><code>xmake clean</code></td><td>清理构建产物</td><td><code>xmake clean</code></td></tr><tr><td><code>xmake build</code></td><td>仅构建指定目标，不运行</td><td><code>xmake build hello</code></td></tr><tr><td><code>xmake install</code></td><td>安装产物到指定目录，<code>-o</code> 指定输出路径</td><td><code>xmake install -o /usr/local</code></td></tr><tr><td><code>xmake package</code></td><td>打包发布（生成安装包/归档）</td><td><code>xmake package</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-快速创建并编译一个-c-控制台程序" tabindex="-1"><a class="header-anchor" href="#示例-1-快速创建并编译一个-c-控制台程序" aria-hidden="true">#</a> 示例 1：快速创建并编译一个 C++ 控制台程序</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 创建项目（生成 main.cpp 和 xmake.lua）</span>
xmake create <span class="token parameter variable">-l</span> c++ <span class="token parameter variable">-t</span> console hello

<span class="token comment"># 2. 进入项目目录</span>
<span class="token builtin class-name">cd</span> hello

<span class="token comment"># 3. 编译（默认 release 模式）</span>
xmake

<span class="token comment"># 4. 运行程序</span>
xmake run
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行后终端会输出编译过程，随后 <code>xmake run</code> 打印出 <code>hello xmake!</code>。生成的 <code>xmake.lua</code> 内容大致如下：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">add_rules</span><span class="token punctuation">(</span><span class="token string">&quot;mode.debug&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;mode.release&quot;</span><span class="token punctuation">)</span>

<span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;hello&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;src/*.cpp&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-切换调试模式并观察优化选项" tabindex="-1"><a class="header-anchor" href="#示例-2-切换调试模式并观察优化选项" aria-hidden="true">#</a> 示例 2：切换调试模式并观察优化选项</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 重新配置为 debug 模式</span>
xmake f <span class="token parameter variable">-m</span> debug

<span class="token comment"># 2. 重新构建</span>
xmake <span class="token parameter variable">-r</span>

<span class="token comment"># 3. 查看链接命令，确认带了 -g 调试信息</span>
xmake <span class="token parameter variable">--verbose</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-跨平台编译到-android-需配置-ndk" tabindex="-1"><a class="header-anchor" href="#示例-3-跨平台编译到-android-需配置-ndk" aria-hidden="true">#</a> 示例 3：跨平台编译到 Android（需配置 NDK）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 配置 Android 平台，指定 NDK 路径</span>
xmake f <span class="token parameter variable">-p</span> android <span class="token parameter variable">--ndk</span><span class="token operator">=</span>/path/to/your/android-ndk <span class="token parameter variable">-m</span> release

<span class="token comment"># 2. 编译</span>
xmake

<span class="token comment"># 3. 打包 APK/AAB 相关的 so 库</span>
xmake package
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-自动下载并链接第三方依赖-如-zlib" tabindex="-1"><a class="header-anchor" href="#示例-4-自动下载并链接第三方依赖-如-zlib" aria-hidden="true">#</a> 示例 4：自动下载并链接第三方依赖（如 zlib）</h3><p>在 <code>xmake.lua</code> 中添加如下依赖配置：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">add_requires</span><span class="token punctuation">(</span><span class="token string">&quot;zlib&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>system <span class="token operator">=</span> <span class="token keyword">false</span><span class="token punctuation">}</span><span class="token punctuation">)</span>

<span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;hello&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;src/*.cpp&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_packages</span><span class="token punctuation">(</span><span class="token string">&quot;zlib&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后在命令行执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 首次会从远程仓库自动下载 zlib 并编译集成</span>
xmake f
xmake
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><ol><li><p><strong>多平台一键切换</strong>：使用 <code>xmake f -p</code> 切换平台后，不同平台的配置会缓存到 <code>.xmake</code> 目录中。交叉编译时可用 <code>xmake f --sdk=/path/to/sdk</code> 指定工具链目录，并配合 <code>--arch=</code> 指定架构（如 <code>arm64</code>、<code>x86_64</code>）。</p></li><li><p><strong>配置文件分层</strong>：核心配置写在项目根目录的 <code>xmake.lua</code>；也可以创建 <code>xmake.rc</code>（顶层全局配置）或每个子目录的 <code>xmake.lua</code> 来分层管理。常用函数如 <code>add_defines()</code> 添加宏定义、<code>add_includedirs()</code> 添加头文件目录、<code>add_linkdirs()</code> 添加链接库目录。</p></li><li><p><strong>与 CMake 项目集成</strong>：如果已有 CMake 工程，可借助 xmake 的 <code>import(&quot;core.project.project&quot;)</code> 或直接调用系统命令来调用 CMake；反过来 CMake 工程也可通过 <code>xmake</code> 的 CMake generator 生成产物。日常使用中，<code>xmake</code> 与 <code>clangd</code>、<code>ccls</code> 等 IDE 工具可通过生成 <code>compile_commands.json</code>（执行 <code>xmake f --cxxflags=</code> 或 <code>xmake project -k compile_commands</code>）配合实现代码补全。</p></li><li><p><strong>环境变量与自动化</strong>：在 CI 中常用 <code>XMAKE_ROOT</code>（xmake 安装根目录）等变量，配合 <code>xmake -P &lt;project&gt;</code> 指定项目目录、<code>xmake --workdir=&lt;dir&gt;</code> 指定工作目录。还可通过 <code>xmake l</code> 直接执行内嵌 Lua 脚本，做自定义构建逻辑扩展。</p></li></ol><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><ul><li><p><strong>xmake.lua 语法报错</strong>：xmake.lua 是 Lua 脚本，注意括号、引号匹配；常见的坑是漏掉 <code>end</code> 或把 Lua 布尔值写成 <code>True/False</code>（应是小写 <code>true/false</code>）。出错时用 <code>xmake</code> 查看带行号的报错定位。</p></li><li><p><strong>切换平台/模式后没生效</strong>：切换后务必执行 <code>xmake -r</code>（强制重编译），否则增量构建可能沿用旧配置导致链接错误或路径错乱。</p></li><li><p><strong>依赖下载失败</strong>：<code>add_requires</code> 从远程拉取包时可能因网络原因失败，可设置镜像源（如 <code>xmake f --pkg_searchdirs=...</code> 或配置国内镜像），或改用 <code>system=true</code> 使用系统已安装的库。</p></li><li><p><strong>头文件找不到/链接失败</strong>：优先检查 <code>add_includedirs</code>、<code>add_linkdirs</code>、<code>add_packages</code> 是否配置完整；交叉编译时尤其要注意工具链与 SDK 路径必须匹配。</p></li><li><p><strong>性能与增量构建</strong>：首次全量编译较慢，后续 xmake 支持增量构建与并行编译（默认多核）。若改动头文件导致大量重编译，可考虑合理拆分 target 以减小编译单元规模。</p></li><li><p><strong>权限问题</strong>：<code>xmake install -o /usr/local</code> 等系统目录安装时需 <code>sudo</code>；交叉编译 Android 时确保 NDK 路径无空格、权限可读。</p></li></ul>`,27),o=[c];function t(i,l){return a(),n("div",null,o)}const u=e(d,[["render",t],["__file","xmake.html.vue"]]);export{u as default};
